    "<svg viewBox=\"0 0 210 210\" width=\"210\" role=\"img\" aria-label=\"Çark: kırmızı 100 derece, mavi 120 derece, sarı 140 derece\"><path d=\"M105 105 L105 10 A95 95 0 0 1 198.6 121.5 Z\" fill=\"#f87171\" stroke=\"#1e293b\" stroke-width=\"1.5\"/><text x=\"151.6\" y=\"70.9\" font-size=\"14\" text-anchor=\"middle\" fill=\"#1e293b\" font-weight=\"bold\">100°</text><path d=\"M105 105 L198.6 121.5 A95 95 0 0 1 43.9 177.8 Z\" fill=\"#60a5fa\" stroke=\"#1e293b\" stroke-width=\"1.5\"/><text x=\"125.8\" y=\"167.1\" font-size=\"14\" text-anchor=\"middle\" fill=\"#1e293b\" font-weight=\"bold\">120°</text><path d=\"M105 105 L43.9 177.8 A95 95 0 0 1 105 10 Z\" fill=\"#facc15\" stroke=\"#1e293b\" stroke-width=\"1.5\"/><text x=\"47.9\" y=\"89.2\" font-size=\"14\" text-anchor=\"middle\" fill=\"#1e293b\" font-weight=\"bold\">140°</text><line x1=\"105\" y1=\"105\" x2=\"80.6\" y2=\"113.9\" stroke=\"#1e293b\" stroke-width=\"3\"/><polygon points=\"69.3,118 78.2,107.3 83,120.5\" fill=\"#1e293b\" stroke=\"#1e293b\" stroke-width=\"1\"/><circle cx=\"105\" cy=\"105\" r=\"6\" fill=\"#1e293b\"/></svg><br>3. çark",
    "<svg viewBox=\"0 0 210 210\" width=\"210\" role=\"img\" aria-label=\"Çark: kırmızı 90 derece, sarı 120 derece, mavi 45 derece, kırmızı 45 derece, mavi 60 derece\"><path d=\"M105 105 L105 10 A95 95 0 0 1 200 105 Z\" fill=\"#f87171\" stroke=\"#1e293b\" stroke-width=\"1.5\"/><text x=\"148\" y=\"67\" font-size=\"14\" text-anchor=\"middle\" fill=\"#1e293b\" font-weight=\"bold\">90°</text><path d=\"M105 105 L200 105 A95 95 0 0 1 57.5 187.3 Z\" fill=\"#facc15\" stroke=\"#1e293b\" stroke-width=\"1.5\"/><text x=\"135.4\" y=\"162.7\" font-size=\"14\" text-anchor=\"middle\" fill=\"#1e293b\" font-weight=\"bold\">120°</text><path d=\"M105 105 L57.5 187.3 A95 95 0 0 1 13.2 129.6 Z\" fill=\"#60a5fa\" stroke=\"#1e293b\" stroke-width=\"1.5\"/><text x=\"56.8\" y=\"147\" font-size=\"14\" text-anchor=\"middle\" fill=\"#1e293b\" font-weight=\"bold\">45°</text><path d=\"M105 105 L13.2 129.6 A95 95 0 0 1 22.7 57.5 Z\" fill=\"#f87171\" stroke=\"#1e293b\" stroke-width=\"1.5\"/><text x=\"44.7\" y=\"102.1\" font-size=\"14\" text-anchor=\"middle\" fill=\"#1e293b\" font-weight=\"bold\">45°</text><path d=\"M105 105 L22.7 57.5 A95 95 0 0 1 105 10 Z\" fill=\"#60a5fa\" stroke=\"#1e293b\" stroke-width=\"1.5\"/><text x=\"74.6\" y=\"57.3\" font-size=\"14\" text-anchor=\"middle\" fill=\"#1e293b\" font-weight=\"bold\">60°</text><line x1=\"105\" y1=\"105\" x2=\"128.6\" y2=\"116\" stroke=\"#1e293b\" stroke-width=\"3\"/><polygon points=\"139.4,121.1 125.6,122.3 131.5,109.6\" fill=\"#1e293b\" stroke=\"#1e293b\" stroke-width=\"1\"/><circle cx=\"105\" cy=\"105\" r=\"6\" fill=\"#1e293b\"/></svg><br>4. çark"
