"315\" y=\"185\" width=\"44\" height=\"30\" rx=\"4\" fill=\"#fca5a5\" stroke=\"#475569\" stroke-width=\"1.2\"/><text x=\"337\" y=\"205\" font-size=\"14\" fill=\"#dc2626\" text-anchor=\"middle\" font-weight=\"bold\">6</text><rect x=\"365\" y=\"185\" width=\"44\" height=\"30\" rx=\"4\" fill=\"white\" stroke=\"#475569\" stroke-width=\"1.2\"/><text x=\"387\" y=\"205\" font-size=\"14\" fill=\"#1e293b\" text-anchor=\"middle\" font-weight=\"bold\">7</text><rect x=\"415\" y=\"185\" width=\"44\" height=\"30\" rx=\"4\" fill=\"#bbf7d0\" stroke=\"#475569\" stroke-width=\"1.2\"/><text x=\"437\" y=\"205\" font-size=\"14\" fill=\"#16a34a\" text-anchor=\"middle\" font-weight=\"bold\">8</text><text x=\"250\" y=\"232\" font-size=\"12\" fill=\"#94a3b8\" text-anchor=\"middle\">koridor</text><rect x=\"40\" y=\"245\" width=\"18\" height=\"14\" rx=\"0\" fill=\"#fca5a5\" stroke=\"#1e293b\" stroke-width=\"1.5\"/><text x=\"64\" y=\"257\" font-size=\"13\" fill=\"#1e293b\" text-anchor=\"start\">Dolu</text><rect x=\"120\" y=\"245\" width=\"18\" height=\"14\" rx=\"0\" fill=\"#bbf7d0\" stroke=\"#1e293b\" stroke-width=\"1.5\"/><text x=\"144\" y=\"257\" font-size=\"13\" fill=\"#1e293b\" text-anchor=\"start\">Boş, uygun (14)</text><rect x=\"290\" y=\"245\" width=\"18\" height=\"14\" rx=\"0\" fill=\"white\" stroke=\"#1e293b\" stroke-width=\"1.5\"/><text x=\"314\" y=\"257\" font-size=\"13\" fill=\"#1e293b\" text-anchor=\"start\">Boş, uygun değil (12)</text></svg><figcaption>Yeşil koltukların iki yanında dolu koltuk yok.</figcaption></figure><div class=\"sv-t\"><b>Püf nokta:</b> Koridor ve blok uçları komşuluk sayısını azaltır; her koltuğu ayrı kontrol et.</div><div class=\"sv-w\"><b>Tuzak:</b> 4 ile 5’i bitişik saymak ya da paydaya 40 yazmak.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>"
